head.script:
scwin.onpageload = function () {
	widgetContainer.addWidgets([{
		id: "widget1",
		title: "위젯1",
		src: "/sample/common_link/widgetContainer_widget_getSrc_WPF-1561_(WSQ-2561)_content.xml",
		scope: true,
		x: 0,
		y: 0,
		unitWidth: 1,
		unitHeight: 1
	}, {
		id: "widget2",
		title: "위젯2",
		src: "/sample/common_link/widgetContainer_widget_getSrc_WPF-1561_(WSQ-2561)_content2.xml",
		scope: true,
		x: 1,
		y: 0,
		unitWidth: 1,
		unitHeight: 1
	}]);
};
scwin.trigger1_onclick = function (e) {
	tbx_result.setValue(widgetContainer.getWidgetById('widget1').getSrc() + " | " + widgetContainer.getWidgetById('widget2').getSrc());
};
